/**
 * Documentation generated by Claude
 * Purpose: Rules for writing and showing campsite reviews.
 * Role / Design Pattern: Pure policy object, kept free of Firebase so it can be unit tested.
 * Outstanding Issues: None.
 */
package com.example.campsitelottery

import java.text.SimpleDateFormat
import java.util.Date
import java.util.Locale

/** Validation and display rules for campsite reviews. */
object ReviewPolicy {

    /** Longest review allowed, in characters, after trimming. */
    const val MAX_LENGTH = 500

    /** Name shown for a review whose author had no profile name. */
    const val ANONYMOUS_NAME = "Anonymous camper"

    /** Removes leading and trailing whitespace, which isn't saved. */
    fun normalize(text: String): String = text.trim()

    /**
     * Checks a review before it is posted.
     *
     * @return why [text] can't be posted, or null if it is fine.
     */
    fun validate(text: String): String? {
        val trimmed = normalize(text)
        return when {
            trimmed.isEmpty() -> "Write something before posting."
            trimmed.length > MAX_LENGTH -> "Reviews can be at most $MAX_LENGTH characters."
            else -> null
        }
    }

    /** @throws IllegalArgumentException if [text] can't be posted. */
    fun requireValid(text: String) {
        validate(text)?.let { throw IllegalArgumentException(it) }
    }

    /** Anyone except the campsite's owner may review it. */
    fun canReview(ownerId: String, userId: String): Boolean =
        userId.isNotBlank() && ownerId != userId

    /** Name to show for [review]'s author. */
    fun displayName(review: Review): String =
        review.authorName.trim().ifEmpty { ANONYMOUS_NAME }

    /** Date shown under a review, e.g. "Nov 22, 2026", or "Just now" before the server sets it. */
    fun displayDate(date: Date?): String =
        date?.let { SimpleDateFormat("MMM d, yyyy", Locale.US).format(it) } ?: "Just now"

    /** Error shown when a review was reposted between an admin reading it and removing it. */
    const val CHANGED_MESSAGE = "This review was edited. Read it again before removing it."

    /**
     * Whether [review] is shown to users. A stored review with no readable text
     * is malformed: only admins see it, so they can remove it.
     */
    fun isShownToUsers(review: Review): Boolean = review.text.isNotBlank()

    /**
     * Reads a stored text field. Anything that isn't a string comes back empty,
     * so a malformed review is still listed and can be removed by an admin.
     */
    fun parseStoredText(raw: Any?): String = raw as? String ?: ""

    /** Newest reviews first; reviews with no date yet (just posted) come first. */
    fun sortNewestFirst(reviews: List<Review>): List<Review> =
        reviews.sortedByDescending { it.updatedAt?.time ?: Long.MAX_VALUE }
}
